private static string calculImpot(StreamWriter writer, int numClient, string[] champs) {
             // request calculation married(Y/N) nbEnfants salaireAnnuel
             // 4 fields are required
            if (champs.Length != 4) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [1]
            string marié = champs[1];
            if (marié != "o" &amp;&amp; marié != "n") {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [2]
            int nbEnfants;
            if (!int.TryParse(champs[2], out nbEnfants)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [3]
            int salaireAnnuel;
            if (!int.TryParse(champs[3], out salaireAnnuel)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // that's it - tax calculation
            int impot = 0;
            try {
                impot = metier.CalculerImpot(marié == "o", nbEnfants, salaireAnnuel);
                return impot.ToString();
            } catch (Exception ex) {
                return ex.Message;
            }
        }
</code></pre> <ul> <li>riga 1: il metodo riceve l'array dei campi del comando come terzo parametro tax. Se formulato correttamente, ha la forma married tax nbEnfants salaireAnnuel. Il risultato del metodo è la risposta da inviare al cliente.   </li> <li>riga 4: verifica che il comando abbia 4 campi   </li> <li>riga 8: verifica che married sia valido   </li> <li>riga 14: verifica che nbEnfants sia valido   </li> <li>riga 19: verifica che salaireAnnuel sia valido   </li> <li>riga 25: l'imposta viene calcolata utilizzando il CalculerImpot del livello [metier]. Ricordare che questo livello è incapsulato in una DLL.   </li> <li>riga 26: se il livello [metier] ha restituito un risultato, questo viene restituito al cliente.   </li> <li>riga 28: se il livello [metier] ha generato un'eccezione, il messaggio di eccezione viene restituito al cliente.   </li> </ul> <p></p>
